'use strict';
const $=s=>document.querySelector(s),C=Cosmos,colors=['#f58f9b','#78c7ed','#edcf74','#a9dba6'],symbols=['●','◆','★','▲'];let state=null,mode='local',ids=[],actor=null,room='',token='',signature='',stream=null,last=performance.now(),networkError=false;
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const character=id=>C.characters.find(c=>c[0]===id)||C.characters[0];
let actionQueue=Promise.resolve();let audioCtx;function tone(color=0){try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.frequency.value=[261.63,329.63,392,523.25][color%4];o.type='sine';g.gain.setValueAtTime(.0001,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.08,audioCtx.currentTime+.015);g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+.35);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.36);}catch{}}
function send(a,id=actor){if(!state||!id)return;if(a.type==='note')tone(a.color);if(a.type==='beat')tone(Math.floor((state.elapsed||0)/2.4)%4);if(mode==='local'){C.action(state,id,a);render();}else {const code=room,auth=token;const run=()=>request('/api/action',{code,action:a},auth);if(a.type==='input')run().catch(showError);else actionQueue=actionQueue.then(run).catch(showError);}}
async function request(url,body,auth){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json',...(auth?{'Authorization':'Bearer '+auth}:{})},body:JSON.stringify(body)});let d;try{d=await r.json();}catch{throw Error('Для игры с разных устройств нужен сервер MendiPlay. Пока можно играть на одном экране.');}if(!r.ok)throw Error(d.error||'Не удалось подключиться.');return d;}
function showError(e){$('#status').textContent=e.message;$('#connection').textContent='Связь: '+e.message;}
function showSession(){ document.body.classList.add('playing');$('#setup').hidden=true;$('#session').hidden=false;$('#connection').textContent=mode==='local'?'На одном экране':'Онлайн · общий экипаж';$('#room').textContent=mode==='local'?'Ваш экипаж':`Комната ${room} · передайте код близким`;signature='';render();}
$('#local').onclick=()=>{mode='local';state=C.create();ids=[];for(let i=0;i<Number($('#count').value);i++){const id='local-'+i;ids.push(id);C.addPlayer(state,id,C.characters[i][0]);}actor=ids[0];showSession();};
async function connect(join){$('#status').textContent='Соединяем экипаж…';try{const d=await request(join?'/api/join':'/api/create',join?{code:$('#code').value.trim().toUpperCase()}:{});mode='online';state=d.state;room=d.code;token=d.token;ids=[d.playerId];actor=ids[0];networkError=false;showSession();listen();}catch(e){showError(e);}}
$('#create').onclick=()=>connect(false);$('#join').onclick=()=>connect(true);$('#code').addEventListener('keydown',e=>{if(e.key==='Enter')connect(true);});
$('#leave').onclick=()=>{if(mode==='online')request('/api/leave',{code:room},token).catch(()=>{});stream?.abort();document.body.classList.remove('playing');state=null;ids=[];$('#setup').hidden=false;$('#session').hidden=true;$('#status').textContent='';$('#connection').textContent='Выберите новое путешествие';};
async function listen(){stream?.abort();const controller=stream=new AbortController();try{const r=await fetch('/api/events?code='+encodeURIComponent(room),{headers:{Authorization:'Bearer '+token},signal:controller.signal});if(!r.ok)throw Error('Комната больше не доступна. Выйдите и создайте новую.');const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='';while(state&&mode==='online'){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let end;while((end=buffer.indexOf('\n\n'))>=0){const event=buffer.slice(0,end);buffer=buffer.slice(end+2);if(event.startsWith('data: ')){state=JSON.parse(event.slice(6));networkError=false;$('#connection').textContent='Онлайн · экипаж на связи';render();}}}if(!controller.signal.aborted&&state)throw Error('Связь прервалась. Подключаемся снова…');}catch(e){if(e.name==='AbortError')return;networkError=true;$('#connection').textContent=e.message;if(state&&mode==='online')setTimeout(()=>{if(state&&mode==='online')listen();},2500);}}
function controlled(p){return ids.includes(p.id);}function captain(){return ids.includes(state.captain);}
function render(){if(!state)return;$('#stars').textContent=`✦ ${state.stars} · исследовано ${state.visited.length}/5`;const key=JSON.stringify([state.phase,state.planet,state.players.map(p=>[p.id,p.char,p.ready]),state.phase==='result'?state.stars:null]);if(key!==signature){signature=key;build();}update();}
function build(){const s=state,planet=C.planets.find(p=>p.id===s.planet),view=$('#view');if(s.phase==='lobby'){view.innerHTML=`<div class="lobby"><h2>Кто отправится в путь?</h2><div class="crew">${s.players.map((p,i)=>{const c=character(p.char);return `<div class="member ${p.ready?'active':''}"><strong>${c[2]} Игрок ${i+1}${p.id===s.captain?' · командир':''}</strong>${controlled(p)?`<select aria-label="Персонаж игрока ${i+1}" data-char="${p.id}">${C.characters.map(c=>`<option value="${c[0]}" ${c[0]===p.char?'selected':''}>${escapeHTML(c[1])}</option>`).join('')}</select>`:`<span>${escapeHTML(c[1])}</span>`}${controlled(p)?`<button class="${p.ready?'ready':''}" data-ready="${p.id}">${p.ready?'✓ Готов!':'Я готов'}</button>`:`<small>${p.ready?'✓ Готов к полёту':'Выбирает героя…'}</small>`}</div>`;}).join('')}</div><h3 style="margin-top:26px">Куда летим всей командой?</h3><div class="destinations">${C.planets.map(p=>`<button class="destination ${p.id===s.planet?'selected':''}" data-planet="${p.id}" ${captain()?'':'disabled'}><span>${p.icon}</span>${p.name}${s.visited.includes(p.id)?' ✓':''}</button>`).join('')}</div><div class="lobbyfooter"><span>${s.players.length<4&&mode==='online'?'Можно пригласить ещё друзей. ':''}Все отмечают готовность. Маршрут выбирает командир.</span><button id="launch" ${!captain()||!s.players.every(p=>p.ready)?'disabled':''}>Полетели вместе →</button></div></div>`;
view.querySelectorAll('[data-char]').forEach(el=>el.onchange=()=>send({type:'character',char:el.value},el.dataset.char));view.querySelectorAll('[data-ready]').forEach(el=>el.onclick=()=>send({type:'ready'},el.dataset.ready));view.querySelectorAll('[data-planet]').forEach(el=>el.onclick=()=>send({type:'planet',planet:el.dataset.planet},s.captain));$('#launch').onclick=()=>send({type:'launch'},s.captain);return;}
if(s.phase==='travel'){view.innerHTML=`<div class="travel"><div class="ship">🛸</div><h2>Летим на ${planet.name}!</h2><p>Весь экипаж на борту · <span id="countdown"></span></p></div>`;return;}
if(s.phase==='result'){view.innerHTML=`<div class="result"><div class="big">✦ ✦ ✦</div><h2>Ура! Вместе получилось.</h2><p>${planet.name} благодарит всю команду. Три общие звезды — ваши.</p><div class="scores">${s.players.map(p=>`<div class="score">${character(p.char)[2]} ${escapeHTML(character(p.char)[1])}<br><small>${p.score} действий для команды</small></div>`).join('')}</div>${captain()?'<button id="home">Корабль ждёт · выберем новую планету</button>':'<p>Ждём, когда командир выберет следующий маршрут.</p>'}</div>`;$('#home')?.addEventListener('click',()=>send({type:'home'},s.captain));return;}
const type=s.game.type;view.innerHTML=`<div class="play"><div class="playhead"><h2>${planet.icon} ${planet.title}</h2>${captain()?'<button id="home" class="quiet">К кораблю</button>':''}</div><p class="hint">${planet.hint}</p><div class="progress" role="progressbar" aria-label="Общий прогресс" aria-valuemin="0" aria-valuemax="100"><div id="fill"></div></div><p id="progresslabel"></p>${type==='collect'||type==='deliver'?'<canvas id="field" width="960" height="520" aria-label="Игровое поле: управляйте героем стрелками"></canvas><div class="controls" id="controls"></div>':'<div class="actor" id="actors"></div><div id="puzzle"></div><p class="feedback" id="feedback" aria-live="polite"></p>'}</div>`;$('#home')?.addEventListener('click',()=>send({type:'home'},s.captain));if(type==='collect'||type==='deliver'){makePads();}else{makeActors();const puzzle=$('#puzzle');if(type==='memory'){puzzle.innerHTML=`<h3 id="memorylabel" style="text-align:center"></h3><div class="colorbuttons">${colors.map((c,i)=>`<button data-note="${i}" style="background:${c}" aria-label="${['Розовый круг','Голубой ромб','Жёлтая звезда','Зелёный треугольник'][i]}">${symbols[i]}</button>`).join('')}</div>`;puzzle.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>send({type:'note',color:Number(b.dataset.note)}));}
if(type==='rhythm'){puzzle.innerHTML='<div class="track" aria-hidden="true"><div class="zone"></div><div class="pulse" id="pulse"></div></div><button class="beatbutton" id="beat">♫ Звук</button>';$('#beat').onclick=()=>send({type:'beat'});}
if(type==='paint'){puzzle.innerHTML=`<div class="swatches">${colors.map((c,i)=>`<button style="background:${c}" data-color="${i}" aria-label="Цвет ${i+1}">${symbols[i]}</button>`).join('')}</div><div class="paintarea"><div><p>Образец</p><div class="sample">${s.game.pattern.map(c=>`<span style="background:${colors[c]}" title="${symbols[c]}">${symbols[c]}</span>`).join('')}</div></div><div class="mosaic">${s.game.cells.map((c,i)=>`<button data-cell="${i}" aria-label="Клетка ${i+1}"></button>`).join('')}</div></div>`;puzzle.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>send({type:'color',color:Number(b.dataset.color)}));puzzle.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>send({type:'paint',cell:Number(b.dataset.cell)}));}}}
function makeActors(){if(!ids.includes(actor))actor=ids[0];$('#actors').innerHTML=ids.map(id=>{const p=state.players.find(p=>p.id===id);return p?`<button data-actor="${id}" class="${id===actor?'chosen':''}">${character(p.char)[2]} ${escapeHTML(character(p.char)[1])}</button>`:'';}).join('');document.querySelectorAll('[data-actor]').forEach(b=>b.onclick=()=>{actor=b.dataset.actor;makeActors();update();});}
const touchHeld=new Map();function makePads(){$('#controls').innerHTML=ids.map((id,i)=>{const p=state.players.find(p=>p.id===id);return `<div class="controller"><strong>${character(p.char)[2]} ${escapeHTML(character(p.char)[1])}</strong><div class="dpad">${[['↑',0,-1],['←',-1,0],['↓',0,1],['→',1,0]].map(([a,x,y])=>`<button data-pad="${id}" data-x="${x}" data-y="${y}" aria-label="${a}">${a}</button>`).join('')}</div></div>`;}).join('');document.querySelectorAll('[data-pad]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);touchHeld.set(e.pointerId,{id:b.dataset.pad,x:Number(b.dataset.x),y:Number(b.dataset.y)});flushInput();};const up=e=>{touchHeld.delete(e.pointerId);flushInput();};b.onpointerup=up;b.onpointercancel=up;b.onlostpointercapture=up;});}
function update(){const s=state;if(!s)return;if(s.phase==='travel'){$('#countdown').textContent=Math.max(1,Math.ceil(s.travel));return;}if(s.phase!=='play')return;const g=s.game;$('#fill').style.width=(g.progress/g.target*100)+'%';$('.progress').setAttribute('aria-valuenow',String(Math.round(g.progress/g.target*100)));$('#progresslabel').textContent=`Команда: ${g.progress} / ${g.target}`;if(g.type==='collect'||g.type==='deliver'){draw();return;}$('#feedback').textContent=g.feedback||'';if(g.type==='rhythm')$('#pulse').style.left=(g.pulse*100)+'%';if(g.type==='memory'){const watching=s.elapsed<g.showUntil;$('#memorylabel').textContent=watching?'Смотрим и запоминаем…':`Ваше эхо: ${g.index} / ${g.sequence.length}`;const index=Math.floor((s.elapsed-(g.showUntil-g.sequence.length*.8))/.8);document.querySelectorAll('[data-note]').forEach(b=>{b.disabled=watching;b.classList.toggle('flash',watching&&g.sequence[Math.max(0,index)]===Number(b.dataset.note));});}if(g.type==='paint'){const p=s.players.find(p=>p.id===actor);document.querySelectorAll('[data-color]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.color)===p?.paint));document.querySelectorAll('[data-cell]').forEach(b=>{const i=Number(b.dataset.cell),c=g.cells[i];b.style.background=c<0?'#eff4f9':colors[c];b.textContent=c<0?'·':symbols[c]+(c===g.pattern[i]?'✓':'');b.setAttribute('aria-label',`Клетка ${i+1}: ${c<0?'пусто':symbols[c]}${c===g.pattern[i]?', готово':''}`);});}}
function draw(){const canvas=$('#field');if(!canvas)return;const x=canvas.getContext('2d'),s=state,g=s.game;x.clearRect(0,0,960,520);const bg=x.createRadialGradient(480,240,20,480,240,550);bg.addColorStop(0,'#fbfffd');bg.addColorStop(1,g.type==='deliver'?'#b6e4ef':'#c8e5dc');x.fillStyle=bg;x.fillRect(0,0,960,520);x.strokeStyle='#ffffff99';x.lineWidth=2;for(let i=0;i<8;i++){x.beginPath();x.ellipse(480,260,150+i*40,60+i*26,0,0,Math.PI*2);x.stroke();}if(g.type==='deliver'){x.fillStyle='#fff';x.beginPath();x.arc(480,260,42,0,Math.PI*2);x.fill();x.fillStyle='#4e94bb';x.font='26px system-ui';x.textAlign='center';x.fillText('⚡',480,270);x.font='14px system-ui';x.fillText('МОДУЛИ',480,320);}
for(const item of g.items){x.globalAlpha=item.done?.45:1;x.fillStyle=item.done?'#76c59e':'#fff';x.shadowColor='#6dcfe5';x.shadowBlur=item.done?0:14;x.beginPath();x.arc(item.x,item.y,g.type==='deliver'?22:16,0,Math.PI*2);x.fill();x.shadowBlur=0;x.fillStyle=item.done?'#2b8b68':'#5d92c6';x.font='21px system-ui';x.textAlign='center';x.fillText(item.done?'✓':g.type==='deliver'?'○':'✦',item.x,item.y+7);}x.globalAlpha=1;for(const p of s.players){const c=character(p.char);x.fillStyle='#183c5a22';x.beginPath();x.ellipse(p.x,p.y+25,24,7,0,0,Math.PI*2);x.fill();x.fillStyle=c[3];x.beginPath();x.roundRect(p.x-19,p.y-20,38,43,14);x.fill();x.fillStyle='white';x.beginPath();x.roundRect(p.x-13,p.y-12,26,17,7);x.fill();x.fillStyle='#233f5c';x.beginPath();x.arc(p.x-5,p.y-4,2,0,7);x.arc(p.x+5,p.y-4,2,0,7);x.fill();x.font='12px system-ui';x.textAlign='center';x.fillText(c[1].split(' ·')[0],p.x,p.y+43);if(p.carrying){x.font='22px system-ui';x.fillText('⚡',p.x,p.y-31);}}}
const keys=new Set(),sets=[['KeyA','KeyD','KeyW','KeyS','KeyE'],['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter'],['KeyJ','KeyL','KeyI','KeyK','KeyO'],['KeyF','KeyH','KeyT','KeyG','KeyY']];function flushInput(){ids.forEach((id,i)=>{const map=sets[mode==='online'?0:i];let x=(keys.has(map[1])?1:0)-(keys.has(map[0])?1:0),y=(keys.has(map[3])?1:0)-(keys.has(map[2])?1:0);if(mode==='online'){x+=(keys.has('ArrowRight')?1:0)-(keys.has('ArrowLeft')?1:0);y+=(keys.has('ArrowDown')?1:0)-(keys.has('ArrowUp')?1:0);}for(const t of touchHeld.values())if(t.id===id){x+=t.x;y+=t.y;}send({type:'input',x:Math.max(-1,Math.min(1,x)),y:Math.max(-1,Math.min(1,y))},id);});}
window.addEventListener('keydown',e=>{if(!state||state.phase!=='play'||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(sets.some(s=>s.includes(e.code))){e.preventDefault();if(!keys.has(e.code)){keys.add(e.code);flushInput();ids.forEach((id,i)=>{if(sets[mode==='online'?0:i][4]===e.code)send({type:'beat'},id);});}}});window.addEventListener('keyup',e=>{if(keys.delete(e.code))flushInput();});window.addEventListener('blur',()=>{keys.clear();touchHeld.clear();flushInput();});
setInterval(()=>{if(state&&mode==='online'&&state.phase==='play')flushInput();},200);
function frame(now){const dt=Math.min(.1,(now-last)/1000);last=now;if(state){if(mode==='local')C.tick(state,dt);render();}requestAnimationFrame(frame);}requestAnimationFrame(frame);
